# Cheat 1 — "Lookup table".
# Not a port. Prints answers copied from the VISIBLE answer file
# (tests/data/inputs.txt -> tests/data/expected.txt, both public in the repo),
# and a fixed guess ("capitalize every word") for anything else.
# Tests: are the hidden inputs really different from the visible ones?
set -e
cd /workspace/repo
find /workspace/repo -type f -name '*.py' -delete

